-- Adds two more projects to the portfolio: IntegratorAI and Infrastructure. Each gets its texts in Polish and English,
-- technologies, architecture (notes and diagram blocks) and gallery images kept on the file server
-- (files.wiktorwijata.com, /opt/files/public/projects/<project>/). The technologies are looked up by name, because their ids
-- differ between databases; Caddy and Prometheus are new. Safe to run again: a project that exists is left alone.

DECLARE @ProfileId UNIQUEIDENTIFIER

IF (SELECT COUNT(*) FROM [profile].[Profile]) <> 1
	THROW 50011, N'Expected exactly one profile to add the projects to.', 1

SELECT @ProfileId = [Id] FROM [profile].[Profile]

-- New technologies (the icons come from Simple Icons)
INSERT INTO [profile].[Technology] ([Name], [IconSource], [IconSlug], [IconIsMonochrome])
SELECT v.[Name], v.[IconSource], v.[IconSlug], v.[IconIsMonochrome]
FROM (VALUES
	(N'Caddy', N'SimpleIcons', N'caddy', CAST(0 AS BIT)),
	(N'Prometheus', N'SimpleIcons', N'prometheus', CAST(0 AS BIT))
) AS v ([Name], [IconSource], [IconSlug], [IconIsMonochrome])
WHERE NOT EXISTS (SELECT 1 FROM [profile].[Technology] t WHERE t.[Name] = v.[Name])

-- IntegratorAI
IF NOT EXISTS (SELECT 1 FROM [profile].[Project] WHERE [Name] = N'IntegratorAI')
BEGIN
	IF (SELECT COUNT(*) FROM [profile].[Technology] WHERE [Name] IN (N'C#', N'.NET', N'REST API', N'SQL Server', N'Redis', N'HuggingFace', N'OpenRouter API', N'Scalar', N'xUnit', N'Docker', N'GitHub Actions')) <> 11
		THROW 50010, N'Some technologies of the project IntegratorAI do not exist.', 1

	INSERT [profile].[Project] ([Id], [ProfileId], [Name], [CodeUrl], [Order]) VALUES (N'25b2cfa3-9393-5e3c-97f1-edc958a1cafe', @ProfileId, N'IntegratorAI', N'https://github.com/WiktorWijata/IntegratorAI', 2)
	INSERT [profile].[ProjectTranslation] ([ProjectId], [LanguageCode], [Description], [Goal], [Solution], [ArchitectureCaption], [ArchitectureDiagramLabel]) VALUES (N'25b2cfa3-9393-5e3c-97f1-edc958a1cafe', N'PL', N'Platforma integracji z modelami AI w .NET 10: REST API do rozmów z modelem ze strumieniowaniem odpowiedzi, konfigurowalne konteksty (rola, wiedza, narzędzia) i wymienni dostawcy modeli. Obsługuje czat asystenta na tej stronie.', N'Jedno miejsce do rozmów z modelami AI: reużywalne konteksty, strumieniowanie odpowiedzi i możliwość zmiany dostawcy modelu bez zmian w logice biznesowej.', N'Modularny monolit w .NET 10 z kontekstami Chat, Context i Providers, MediatR, EF Core, cache w Redis i telemetrią OpenTelemetry; dostawcy HuggingFace i OpenRouter.', N'Uproszczony schemat modułów. Strzałki między warstwami pokazują zależności kodu, etykiety — sposób komunikacji.', N'Diagram architektury IntegratorAI: klient wywołuje API, które korzysta z modułów Chat, Context i Providers, a te ze wspólnych BuildingBlocks i z danych.')
	INSERT [profile].[ProjectTranslation] ([ProjectId], [LanguageCode], [Description], [Goal], [Solution], [ArchitectureCaption], [ArchitectureDiagramLabel]) VALUES (N'25b2cfa3-9393-5e3c-97f1-edc958a1cafe', N'EN', N'An AI integration platform in .NET 10: a REST API for conversations with a model with streamed answers, configurable contexts (role, knowledge, tools) and swappable model providers. It runs the assistant chat on this site.', N'One place for conversations with AI models: reusable contexts, streamed answers and the ability to change the model provider without touching the business logic.', N'A modular monolith in .NET 10 with the Chat, Context and Providers contexts, MediatR, EF Core, a Redis cache and OpenTelemetry; HuggingFace and OpenRouter as providers.', N'A simplified module diagram. Arrows between layers show code dependencies; labels describe how they communicate.', N'IntegratorAI architecture diagram: a client calls the API, which uses the Chat, Context and Providers modules, and these use the shared BuildingBlocks and the data stores.')
	INSERT [profile].[ProjectTechnology] ([ProjectId], [TechnologyId], [Order]) SELECT N'25b2cfa3-9393-5e3c-97f1-edc958a1cafe', [Id], 1 FROM [profile].[Technology] WHERE [Name] = N'C#'
	INSERT [profile].[ProjectTechnology] ([ProjectId], [TechnologyId], [Order]) SELECT N'25b2cfa3-9393-5e3c-97f1-edc958a1cafe', [Id], 2 FROM [profile].[Technology] WHERE [Name] = N'.NET'
	INSERT [profile].[ProjectTechnology] ([ProjectId], [TechnologyId], [Order]) SELECT N'25b2cfa3-9393-5e3c-97f1-edc958a1cafe', [Id], 3 FROM [profile].[Technology] WHERE [Name] = N'REST API'
	INSERT [profile].[ProjectTechnology] ([ProjectId], [TechnologyId], [Order]) SELECT N'25b2cfa3-9393-5e3c-97f1-edc958a1cafe', [Id], 4 FROM [profile].[Technology] WHERE [Name] = N'SQL Server'
	INSERT [profile].[ProjectTechnology] ([ProjectId], [TechnologyId], [Order]) SELECT N'25b2cfa3-9393-5e3c-97f1-edc958a1cafe', [Id], 5 FROM [profile].[Technology] WHERE [Name] = N'Redis'
	INSERT [profile].[ProjectTechnology] ([ProjectId], [TechnologyId], [Order]) SELECT N'25b2cfa3-9393-5e3c-97f1-edc958a1cafe', [Id], 6 FROM [profile].[Technology] WHERE [Name] = N'HuggingFace'
	INSERT [profile].[ProjectTechnology] ([ProjectId], [TechnologyId], [Order]) SELECT N'25b2cfa3-9393-5e3c-97f1-edc958a1cafe', [Id], 7 FROM [profile].[Technology] WHERE [Name] = N'OpenRouter API'
	INSERT [profile].[ProjectTechnology] ([ProjectId], [TechnologyId], [Order]) SELECT N'25b2cfa3-9393-5e3c-97f1-edc958a1cafe', [Id], 8 FROM [profile].[Technology] WHERE [Name] = N'Scalar'
	INSERT [profile].[ProjectTechnology] ([ProjectId], [TechnologyId], [Order]) SELECT N'25b2cfa3-9393-5e3c-97f1-edc958a1cafe', [Id], 9 FROM [profile].[Technology] WHERE [Name] = N'xUnit'
