	INSERT [profile].[ProjectTechnology] ([ProjectId], [TechnologyId], [Order]) SELECT N'25b2cfa3-9393-5e3c-97f1-edc958a1cafe', [Id], 11 FROM [profile].[Technology] WHERE [Name] = N'GitHub Actions'

	INSERT [profile].[ProjectArchitectureNote] ([Id], [ProjectId], [Order]) VALUES (N'dedd35c8-684c-5c59-84ee-2cdbef827f88', N'25b2cfa3-9393-5e3c-97f1-edc958a1cafe', 1)
	INSERT [profile].[ProjectArchitectureNoteTranslation] ([ProjectArchitectureNoteId], [LanguageCode], [Title], [Text]) VALUES (N'dedd35c8-684c-5c59-84ee-2cdbef827f88', N'PL', N'Modularny monolit', N'Chat, Context i Providers mają własne projekty Contracts, Application, Domain, Persistence i Infrastructure. Moduły rozmawiają przez kontrakty, a host API rejestruje ich implementacje.')
	INSERT [profile].[ProjectArchitectureNoteTranslation] ([ProjectArchitectureNoteId], [LanguageCode], [Title], [Text]) VALUES (N'dedd35c8-684c-5c59-84ee-2cdbef827f88', N'EN', N'Modular monolith', N'Chat, Context and Providers each have their own Contracts, Application, Domain, Persistence and Infrastructure projects. The modules talk through contracts and the API host registers their implementations.')
	INSERT [profile].[ProjectArchitectureNote] ([Id], [ProjectId], [Order]) VALUES (N'd670f087-398f-5afb-a14b-8ce8a00fbaea', N'25b2cfa3-9393-5e3c-97f1-edc958a1cafe', 2)
	INSERT [profile].[ProjectArchitectureNoteTranslation] ([ProjectArchitectureNoteId], [LanguageCode], [Title], [Text]) VALUES (N'd670f087-398f-5afb-a14b-8ce8a00fbaea', N'PL', N'Strumieniowanie i narzędzia', N'Odpowiedź płynie jako Server-Sent Events. Model może poprosić o narzędzie (zdarzenie tool_call); klient wykonuje je i odsyła wynik, a rozmowa czekająca na wyniki odrzuca nowe pytanie kodem 409.')
	INSERT [profile].[ProjectArchitectureNoteTranslation] ([ProjectArchitectureNoteId], [LanguageCode], [Title], [Text]) VALUES (N'd670f087-398f-5afb-a14b-8ce8a00fbaea', N'EN', N'Streaming and tools', N'The answer flows as Server-Sent Events. The model can ask for a tool (a tool_call event); the client runs it and sends the result back, and a conversation waiting for results rejects a new prompt with a 409.')
	INSERT [profile].[ProjectArchitectureNote] ([Id], [ProjectId], [Order]) VALUES (N'deba9eb9-ceef-5d2c-b3a9-b1cb0ee7df93', N'25b2cfa3-9393-5e3c-97f1-edc958a1cafe', 3)
	INSERT [profile].[ProjectArchitectureNoteTranslation] ([ProjectArchitectureNoteId], [LanguageCode], [Title], [Text]) VALUES (N'deba9eb9-ceef-5d2c-b3a9-b1cb0ee7df93', N'PL', N'Wymienni dostawcy', N'Odpowiada dostawca z aktywnym wierszem w tabeli providers.Provider, zapamiętany w Redis. OpenRouter dostaje narzędzia natywnie, HuggingFace na razie je pomija.')
	INSERT [profile].[ProjectArchitectureNoteTranslation] ([ProjectArchitectureNoteId], [LanguageCode], [Title], [Text]) VALUES (N'deba9eb9-ceef-5d2c-b3a9-b1cb0ee7df93', N'EN', N'Swappable providers', N'The provider with the active row in the providers.Provider table answers, cached in Redis. OpenRouter gets the tools natively; HuggingFace ignores them for now.')
	INSERT [profile].[ProjectArchitectureNote] ([Id], [ProjectId], [Order]) VALUES (N'619e46ff-e7e6-5d15-856c-ed692419a7df', N'25b2cfa3-9393-5e3c-97f1-edc958a1cafe', 4)
	INSERT [profile].[ProjectArchitectureNoteTranslation] ([ProjectArchitectureNoteId], [LanguageCode], [Title], [Text]) VALUES (N'619e46ff-e7e6-5d15-856c-ed692419a7df', N'PL', N'Czat tego portfolio', N'Asystent na tej stronie korzysta z IntegratorAI: Portfolio.Api wysyła pytanie, odpowiedź płynie strumieniem do przeglądarki, a kontekst asystenta (rola, wiedza o portfolio, narzędzia) jest synchronizowany z IntegratorAI. Narzędzia wykonuje Portfolio.')
	INSERT [profile].[ProjectArchitectureNoteTranslation] ([ProjectArchitectureNoteId], [LanguageCode], [Title], [Text]) VALUES (N'619e46ff-e7e6-5d15-856c-ed692419a7df', N'EN', N'The chat of this portfolio', N'The assistant on this site runs on IntegratorAI: Portfolio.Api sends the question, the answer is streamed to the browser, and the assistant context (role, knowledge about the portfolio, tools) is synchronized with IntegratorAI. The tools are run by Portfolio.')
	INSERT [profile].[ProjectArchitectureNote] ([Id], [ProjectId], [Order]) VALUES (N'c5bff0ba-6aca-502b-a238-8a996a2f746b', N'25b2cfa3-9393-5e3c-97f1-edc958a1cafe', 5)
	INSERT [profile].[ProjectArchitectureNoteTranslation] ([ProjectArchitectureNoteId], [LanguageCode], [Title], [Text]) VALUES (N'c5bff0ba-6aca-502b-a238-8a996a2f746b', N'PL', N'Testy i obserwowalność', N'Każdy kontekst ma testy jednostkowe i integracyjne (xUnit, NSubstitute), a API ma instrumentację OpenTelemetry.')
	INSERT [profile].[ProjectArchitectureNoteTranslation] ([ProjectArchitectureNoteId], [LanguageCode], [Title], [Text]) VALUES (N'c5bff0ba-6aca-502b-a238-8a996a2f746b', N'EN', N'Tests and observability', N'Every context has unit and integration tests (xUnit, NSubstitute), and the API is instrumented with OpenTelemetry.')

