-- Infrastructure
IF NOT EXISTS (SELECT 1 FROM [profile].[Project] WHERE [Name] = N'Infrastructure')
BEGIN
	IF (SELECT COUNT(*) FROM [profile].[Technology] WHERE [Name] IN (N'Docker', N'GitHub Actions', N'SQL Server', N'Redis', N'Grafana', N'Caddy', N'Prometheus')) <> 7
		THROW 50010, N'Some technologies of the project Infrastructure do not exist.', 1

	INSERT [profile].[Project] ([Id], [ProfileId], [Name], [CodeUrl], [Order]) VALUES (N'ddfcbe2b-442b-5501-9b47-e4f867be8c7b', @ProfileId, N'Infrastructure', NULL, 3)
	INSERT [profile].[ProjectTranslation] ([ProjectId], [LanguageCode], [Description], [Goal], [Solution], [ArchitectureCaption], [ArchitectureDiagramLabel]) VALUES (N'ddfcbe2b-442b-5501-9b47-e4f867be8c7b', N'PL', N'Infrastruktura jako kod dla moich aplikacji na jednym VPS: izolowane środowiska dev i prod, wspólny reverse proxy, bazy danych i pełne monitorowanie, wdrażane workflowami GitHub Actions.', N'Powtarzalne środowiska dla wszystkich projektów na jednym serwerze, w których nowa aplikacja wymaga tylko pliku routingu i skryptu bazy.', N'Caddy jako jeden reverse proxy, osobna sieć Docker, MSSQL i Redis dla każdego środowiska, stos Prometheus, Loki, Tempo i Grafana oraz reużywalne workflowy GitHub Actions.', N'Uproszczony schemat. Środowiska są od siebie odizolowane, a proxy, monitoring i serwer plików są wspólne.', N'Diagram infrastruktury: Caddy kieruje ruch do środowisk dev i prod, a monitoring i serwer plików obsługują oba środowiska.')
	INSERT [profile].[ProjectTranslation] ([ProjectId], [LanguageCode], [Description], [Goal], [Solution], [ArchitectureCaption], [ArchitectureDiagramLabel]) VALUES (N'ddfcbe2b-442b-5501-9b47-e4f867be8c7b', N'EN', N'Infrastructure as code for my applications on a single VPS: isolated dev and prod environments, a shared reverse proxy, databases and full monitoring, deployed with GitHub Actions workflows.', N'Repeatable environments for all projects on one server, where a new application needs only a routing file and a database script.', N'Caddy as the single reverse proxy, a separate Docker network, MSSQL and Redis for every environment, a Prometheus, Loki, Tempo and Grafana stack, and reusable GitHub Actions workflows.', N'A simplified diagram. The environments are isolated from each other, while the proxy, the monitoring and the file server are shared.', N'Infrastructure diagram: Caddy routes traffic to the dev and prod environments, and the monitoring and the file server serve both.')
	INSERT [profile].[ProjectTechnology] ([ProjectId], [TechnologyId], [Order]) SELECT N'ddfcbe2b-442b-5501-9b47-e4f867be8c7b', [Id], 1 FROM [profile].[Technology] WHERE [Name] = N'Docker'
	INSERT [profile].[ProjectTechnology] ([ProjectId], [TechnologyId], [Order]) SELECT N'ddfcbe2b-442b-5501-9b47-e4f867be8c7b', [Id], 2 FROM [profile].[Technology] WHERE [Name] = N'GitHub Actions'
	INSERT [profile].[ProjectTechnology] ([ProjectId], [TechnologyId], [Order]) SELECT N'ddfcbe2b-442b-5501-9b47-e4f867be8c7b', [Id], 3 FROM [profile].[Technology] WHERE [Name] = N'SQL Server'
