	INSERT [profile].[ProjectArchitectureNote] ([Id], [ProjectId], [Order]) VALUES (N'3a93f8b0-9bf2-5300-933b-713ca88a1524', N'ddfcbe2b-442b-5501-9b47-e4f867be8c7b', 1)
	INSERT [profile].[ProjectArchitectureNoteTranslation] ([ProjectArchitectureNoteId], [LanguageCode], [Title], [Text]) VALUES (N'3a93f8b0-9bf2-5300-933b-713ca88a1524', N'PL', N'Izolowane środowiska', N'Każde środowisko ma własną sieć Docker, instancję MSSQL i Redis. Jedna instancja bazy obsługuje wszystkie aplikacje środowiska, a każda aplikacja ma w niej własną bazę.')
	INSERT [profile].[ProjectArchitectureNoteTranslation] ([ProjectArchitectureNoteId], [LanguageCode], [Title], [Text]) VALUES (N'3a93f8b0-9bf2-5300-933b-713ca88a1524', N'EN', N'Isolated environments', N'Every environment has its own Docker network, MSSQL instance and Redis. One database instance serves all the applications of an environment, and each application has its own database in it.')
	INSERT [profile].[ProjectArchitectureNote] ([Id], [ProjectId], [Order]) VALUES (N'67544104-8145-507e-88f5-63805d6303af', N'ddfcbe2b-442b-5501-9b47-e4f867be8c7b', 2)
	INSERT [profile].[ProjectArchitectureNoteTranslation] ([ProjectArchitectureNoteId], [LanguageCode], [Title], [Text]) VALUES (N'67544104-8145-507e-88f5-63805d6303af', N'PL', N'Konwencja dla aplikacji', N'Nowa aplikacja dodaje plik routing.caddy i skrypt init.sql; Caddy sam je wczytuje, więc nie trzeba edytować żadnego wspólnego pliku.')
	INSERT [profile].[ProjectArchitectureNoteTranslation] ([ProjectArchitectureNoteId], [LanguageCode], [Title], [Text]) VALUES (N'67544104-8145-507e-88f5-63805d6303af', N'EN', N'A convention for applications', N'A new application adds a routing.caddy file and an init.sql script; Caddy loads them by itself, so no shared file has to be edited.')
	INSERT [profile].[ProjectArchitectureNote] ([Id], [ProjectId], [Order]) VALUES (N'a7df7218-5286-53be-89e5-cc52363d1817', N'ddfcbe2b-442b-5501-9b47-e4f867be8c7b', 3)
	INSERT [profile].[ProjectArchitectureNoteTranslation] ([ProjectArchitectureNoteId], [LanguageCode], [Title], [Text]) VALUES (N'a7df7218-5286-53be-89e5-cc52363d1817', N'PL', N'Wdrożenia z repozytoriów aplikacji', N'Infrastruktura dostarcza tylko wspólne zasoby: proxy, bazy, Redis i monitoring. Każda aplikacja wdraża się z własnego repozytorium.')
	INSERT [profile].[ProjectArchitectureNoteTranslation] ([ProjectArchitectureNoteId], [LanguageCode], [Title], [Text]) VALUES (N'a7df7218-5286-53be-89e5-cc52363d1817', N'EN', N'Deployments from the application repositories', N'The infrastructure provides only the shared resources: the proxy, the databases, Redis and the monitoring. Each application deploys from its own repository.')
	INSERT [profile].[ProjectArchitectureNote] ([Id], [ProjectId], [Order]) VALUES (N'0bad091a-3811-5501-bbb0-82578f8eb865', N'ddfcbe2b-442b-5501-9b47-e4f867be8c7b', 4)
	INSERT [profile].[ProjectArchitectureNoteTranslation] ([ProjectArchitectureNoteId], [LanguageCode], [Title], [Text]) VALUES (N'0bad091a-3811-5501-bbb0-82578f8eb865', N'PL', N'Monitoring', N'Promtail zbiera logi kontenerów bez konfiguracji per aplikacja, Tempo przyjmuje ślady OTLP, a Grafana jest dostępna po zalogowaniu.')
	INSERT [profile].[ProjectArchitectureNoteTranslation] ([ProjectArchitectureNoteId], [LanguageCode], [Title], [Text]) VALUES (N'0bad091a-3811-5501-bbb0-82578f8eb865', N'EN', N'Monitoring', N'Promtail collects the container logs with no per-application configuration, Tempo accepts OTLP traces, and Grafana is available after logging in.')
	INSERT [profile].[ProjectArchitectureNote] ([Id], [ProjectId], [Order]) VALUES (N'1e78385c-d2a0-5034-8897-23d36cf2e21e', N'ddfcbe2b-442b-5501-9b47-e4f867be8c7b', 5)
	INSERT [profile].[ProjectArchitectureNoteTranslation] ([ProjectArchitectureNoteId], [LanguageCode], [Title], [Text]) VALUES (N'1e78385c-d2a0-5034-8897-23d36cf2e21e', N'PL', N'Serwer plików', N'Zdjęcia projektów, w tym te na tej stronie, serwuje Caddy jako statyczny serwer plików wspólny dla obu środowisk.')
	INSERT [profile].[ProjectArchitectureNoteTranslation] ([ProjectArchitectureNoteId], [LanguageCode], [Title], [Text]) VALUES (N'1e78385c-d2a0-5034-8897-23d36cf2e21e', N'EN', N'File server', N'The project pictures, including the ones on this site, are served by Caddy as a static file server shared by both environments.')

